local _, ns = ...
local Translate = ns.Lore.Translate

Translate("deDE", "skywall", {
	title = "Skywall",
	aliases = { "Reich der Luft", "Ebene der Luft" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Skywall ist das Reich der Luft, eine der vier Domänen der Elementarebene. Es ist ein endloser Himmel aus Stürmen und Strömungen, ohne Boden darunter und ohne Decke darüber. Sein Herr ist {link:al-akir}Al'Akir{/link}, der Windfürst, und seine eingeborenen Kinder sind die Geister und Elementare des Windes. Für die meisten Völker {link:azeroth}Azeroth{/link}s ist Skywall nur ein Name in den Lehren der Schamanen. Für die {link:skyborne}Skyborne{/link} ist es seit zehntausend Jahren die Heimat.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Einst wüteten die Elementarfürsten über die junge Welt. Im ersten Zeitalter dienten sie den Alten Göttern, und als die Diener der Titanen jenes dunkle Reich zerschlugen, wurden die Elementare aus der Welt verstoßen und in einem abgesonderten Reich gebunden. Jeder Fürst erhielt seine eigene Domäne. Die Luft fiel an {link:al-akir}Al'Akir{/link}. Seither weht der Wind von Skywall jenseits der Blicke der Sterblichen, und nur wenige, die es betraten, kehrten zurück, um davon zu erzählen.]=],
		},
		{
			title = "Die verborgenen Inseln",
			text = [=[In den langen Zeitaltern nach dem {link:war-of-the-ancients}Krieg der Ahnen{/link} fanden Elfen auf der Flucht aus Eldre'Thalas Zuflucht in Skywall. Geister des Windes hoben ihr Land in den Himmel und setzten es in einen stillen Winkel des Reiches, auf den das Auge des Windfürsten nicht fiel. Die {link:skyborne}shen'dorei{/link} errichteten dort eine verstreute Schar von Inselprovinzen. {link:zephras-isle}Zephras Isle{/link} war eine davon. Anvilas und Siroccas mit ihren Städten Shen'dramar und New Eldre'naar waren andere. Einst trugen Windströmungen, die man Himmelsströme nannte, Reisende von Insel zu Insel. Diese Wege sind längst verschlossen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:refuge-pointe}Die Zuflucht{/link} hat versagt. Die Geister, die die Inseln bewachten, verschwanden vor langer Zeit, und die {link:anchor-pylons}Ankerpylonen{/link}, die {link:zephras-isle}Zephras{/link} an seinem Platz hielten, waren zugleich die Schutzbanne, die es verbargen. Diese Schutzbanne sind gefallen. Ein Fürst des Ostwinds hat die Insel mit eigenen Augen gesehen, und er hat versprochen, dass {link:al-akir}Al'Akir{/link} davon erfahren wird. Kein {link:skyborne}shen'dorei{/link} kann sagen, wann sich der Windfürst ihnen zuwenden wird. Alle wissen, dass er es tun wird.]=],
		},
	},
})

Translate("deDE", "zephras-isle", {
	title = "Zephras Isle",
	aliases = { "Zephras" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zephras Isle schwebt in {link:skywall}Skywall{/link}, dem Reich der Luft, fern von jeder Küste {link:azeroth}Azeroth{/link}s. Sie ist die Heimat der {link:skyborne}Skyborne{/link}, der Elfen, die sich selbst shen'dorei nennen. Große Bäume erheben sich über ihren nördlichen Hainen, blaue Hochlande ziehen sich über ihre Mitte, und an ihrem südöstlichen Rand liegt der Hafen {link:valanaar}Valanaar{/link}. Wasserfälle stürzen von ihren Klippen in den offenen Himmel. Zehntausend Jahre lang war die Insel eine verborgene Zuflucht. Nun zerfällt sie, und ihr Volk hat begonnen, hinabzublicken, auf eine Welt, aus der seine Vorfahren flohen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die {link:skyborne}shen'dorei{/link} stammen von Rebellen aus Eldre'Thalas ab, der Stadt der Hochgeborenen in {link:feralas}Feralas{/link}, die heute {red:dire-maul}Düsterbruch{/red} heißt. Sie erhoben sich gegen Prinz {red:tortheldrin}Tortheldrin{/red}, verloren ihren Krieg und flohen nach Westen über das Meer. Als die Schiffe des Prinzen näher kamen, hoben Geister des Windes ein großes Stück Land in den Himmel und trugen es aus der Welt hinaus. Sie verankerten es mit uralten Pylonen in {link:skywall}Skywall{/link}, und dort errichteten die Verbannten eine kleine, lichte Zivilisation zwischen den Wolken. Ihr Gründer, der maskierte Rebell, den man den {link:flight-from-eldre-thalas}Shal'nan{/link} nannte, übergab seine Macht später einem vom Volk gewählten Rat.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Vor mehreren Jahrhunderten verschwanden die {link:vanishing-of-the-wind-spirits}Windgeister{/link} ohne ein Wort. Seither werden die Pylonen schwächer, und ganze Bezirke sind in den Himmel gestürzt. {link:ruins-of-ban-aethal}Ban'aethal{/link} fiel in einer einzigen Nacht. Die Verbindung zu den anderen Inseln der {link:skyborne}shen'dorei{/link} ist verloren, und Flüchtlinge, die Zephras erreichten, drängen sich nun in {link:valanaar}Valanaar{/link} oder wenden sich dem Räuberwesen zu. In diese Furcht hinein kamen die {link:al-aketh}Al'Aketh{/link}, ein Kult des {link:al-akir}Al'Akir{/link} unter der Führung der {link:high-priestess-lorthuna}Hohepriesterin Lorthuna{/link}. Sie nahmen {link:falaath-village}Falaath Village{/link} und den {link:shrine-of-akir}Shrine of Akir{/link} ein und schlugen gegen {link:morgan-s-vigil}die Wacht{/link}ürme der Pylonen los. Ihr Ziel war es, die Schutzbanne zu brechen, die die Insel verbargen. Die {link:windshapers}Windshapers{/link} und der {link:high-order}High Order{/link} verachten einander, doch sie standen mit {link:valennia-stormfist}Valennia{/link} Stormfists {link:peacekeepers}Peacekeepers{/link} gegen den Kult, und der Kult wurde zerschlagen. Sein Werk nicht. Die Schutzbanne sind fort, und ein Fürst aus dem Heer des Windfürsten hat Zephras gesehen. Nun sendet jeder Orden seine Jungen nach {link:azeroth}Azeroth{/link}: die Windshapers zum {link:earthen-ring}Irdenen Ring{/link} in {link:mulgore}Mulgore{/link}, der High Order zu den {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Der Ältestenrat.{/b} Der Hochälteste {link:talaanis-shadowsong}Talaanis Shadowsong{/link} führt den Rat der Insel von {link:valanaar}Valanaar{/link} aus.
• {b}Die {link:windshapers}Windshapers{/link}.{/b} Schamanen und Seher, die die heiligen Steine hüten und die verlorenen Geister suchen.
• {b}Der {link:high-order}High Order{/link}.{/b} Magister hochgeborenen Blutes, die die Magie der Insel selbst meistern wollen.
• {b}Die {link:peacekeepers}Peacekeepers{/link}.{/b} Die Miliz der Insel, das Nächste, was die {link:skyborne}shen'dorei{/link} an einem Heer besitzen.
• {b}Die {link:al-aketh}Al'Aketh{/link}.{/b} Eiferer des Windfürsten, versprengt, aber nicht vernichtet.
• {b}Die Nightclaw.{/b} Ein verschwiegener Zirkel von Druiden im {link:shadowgale-forest}Shadowgale Forest{/link}.
• {b}Tiere.{/b} Vuldren, Ursera, Prideclaws, Hippogryphen und Shrieklings, viele von ihnen verwildert, seit die Winde verstummten.]=],
		},
		{
			title = "Überlieferungen der Insel",
			text = [=[• Ein {link:skyborne}shen'dorei{/link}, der mündig wird, erhält ein Erbstück, das einst jemand trug, der vor ihm kam. Wenn dessen Träger stirbt, wird das Erbstück für den nächsten Jugendlichen geborgen.
• Die Toten werden verbrannt, und ihre Asche wird den Winden übergeben.
• Windsteine, blaue Edelsteine voll rohen Windes, erhellen und wärmen heute die meisten Häuser der Insel.
• Kleine Erinnerungskristalle bewahren Stimmen. Berührt man sie, lassen sie eine Aufzeichnung leise durch die Luft treiben.]=],
		},
	},
})

Translate("deDE", "thendal-village", {
	title = "Thendal Village",
	aliases = { "Thendal Grove" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thendal Village liegt in den nördlichen Hainen von {link:zephras-isle}Zephras{/link}, wo die jungen {link:skyborne}shen'dorei{/link} mündig werden. Seine Häuser sind in und um einen gewaltigen Großvaterbaum gebaut, und seine Waldläufer wahren das Gleichgewicht der Wälder. {link:rorian-the-dayseeker}Rorian the Dayseeker{/link} führt das Dorf. Älteste des Rates kommen hierher, um die Jungen zu prüfen und sie hinaus auf die Insel zu schicken. Östlich des Dorfes stehen die Thendal Standing Stones, ein Ort des Windes und der Leylinien. Einen Pass hinauf im Nordosten liegt der Rise of Spirits, wo die Novizen der {link:windshapers}Windshapers{/link} das heilige Sapta trinken. Ursera hausen in einer Höhle im Süden. In letzter Zeit ist der Kult sogar bis hierher gekommen.]=],
		},
	},
})

Translate("deDE", "shen-dar-village", {
	title = "Shen'dar Village",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shen'dar Village ist der erste Ort südlich der nördlichen Haine, gelegen in den blauen Hügeln der {link:shen-dar-highlands}Shen'dar Highlands{/link}. {link:constable-aonda}Konstablerin Aonda{/link} wahrt hier den Frieden mit zu wenigen {link:peacekeepers}Peacekeepers{/link}. Beide Orden haben hier Älteste: {link:illaya-amberwind}Illaya Amberwind{/link} für die {link:windshapers}Windshapers{/link} und {link:rathiril-sunlance}Rathiril Sunlance{/link} für den {link:high-order}High Order{/link}, und sie sind sich in wenig einig. Coriella Calmbreeze führt das Gasthaus. Eine Zeit lang duldete das Dorf eine Missionarin der {link:al-aketh}Al'Aketh{/link} in seinen Straßen. Dieser Frieden endete, als sich der Kult in Falaath sammelte, um das Dorf anzugreifen, und die Dorfbewohner zuerst zuschlugen.]=],
		},
	},
})

Translate("deDE", "shen-dar-highlands", {
	title = "Shen'dar Highlands",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Shen'dar Highlands sind das hügelige Herz von {link:zephras-isle}Zephras{/link}. Ihre stehenden Steine sind den {link:windshapers}Windshapers{/link} heilig, die sie gegen die neugierigen Magister des {link:high-order}High Order{/link} bewachen. An diesen Steinen ist zwischen den beiden Orden Blut vergossen worden. Räuber verstecken sich in einer Höhle hinter einem Wasserfall im Norden, Hippogryphen nisten im Süden, und Prideclaws streifen nahe beim Dorf umher. Auf einem Hügel beim Pylon des Hochlands lebt ein schelmischer alter Waldgeist, Kuramaa. Die geflügelte Vuldren Vulgara jagt in den Hügeln, und die {link:peacekeepers}Peacekeepers{/link} haben einen Preis auf ihren Kopf ausgesetzt.]=],
		},
	},
})

Translate("deDE", "falaath-village", {
	title = "Falaath Village",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Falaath Village liegt in Trümmern in den {link:shen-dar-highlands}Shen'dar Highlands{/link}, und die {link:al-aketh}Al'Aketh{/link} haben es zu ihrem eigenen gemacht. Missionare empfangen neue Bekehrte an seinem Tor und zeichnen sie mit dem Zeichen Akirs. Zwischen seinen zerbrochenen Häusern nehmen Stürme Gestalt an, herbeigerufen von den Sturmrufern des Kults. Im Gasthaus von Falaath empfing {link:skypriest-aanders}Himmelspriester Aanders{/link} heimlich die {link:high-priestess-lorthuna}Hohepriesterin Lorthuna{/link}, und dort plante der Kult seine zwei Schläge gegen {link:shen-dar-village}Shen'dar Village{/link} und den westlichen Wachturm. Kommandant Cyclas sollte den ersten anführen. Er erlebte es nicht mehr.]=],
		},
	},
})

Translate("deDE", "windsong-lake", {
	title = "Windsong Lake",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Windsong Lake liegt in der Mitte von {link:zephras-isle}Zephras{/link}, zwischen dem Hochland und dem Schrein. Krabben, die man Windsong Crawlers nennt, leben an seinen Ufern und in den Flüssen, die ihn speisen, und nirgendwo sonst auf der Welt. Man kann sie nur wenige Wochen im Jahr fangen. Einst waren die Crawlers eine Köstlichkeit, die zu den anderen Inseln der {link:skyborne}shen'dorei{/link} gebracht wurde. Konstrukte, ein Geschenk der {link:vanishing-of-the-wind-spirits}Windgeister{/link}, fischten früher mit Netzen im See. Als die Pylonen zu versagen begannen, sanken viele von ihnen auf seinen Grund, und einige liegen noch immer dort.]=],
		},
	},
})

Translate("deDE", "west-pylon-watchtower", {
	title = "West Pylon Watchtower",
	aliases = { "westlicher Wachturm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der West Pylon Watchtower bewacht einen der {link:anchor-pylons}Ankerpylonen{/link} am südwestlichen Rand der {link:shen-dar-highlands}Shen'dar Highlands{/link}. {link:peacekeepers}Peacekeepers{/link} hielten ihn, bis die {link:al-aketh}Al'Aketh{/link} kamen. {link:skypriest-aanders}Himmelspriester Aanders{/link} führte den Angriff, und die Verteidiger starben auf ihrem Posten. Unter ihnen war der Neffe des Hochältesten {link:talaanis-shadowsong}Talaanis Shadowsong{/link}, dessen Familiensiegelring am Turm gefunden wurde. Was der Himmelspriester dort mit dem Pylon tat, ist nicht verzeichnet. Der Rat wusste nur, dass der Kult wegen des Turms gekommen war und nicht wegen der Soldaten darin.]=],
		},
	},
})

Translate("deDE", "valanaar", {
	title = "Valanaar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Valanaar ist der Hafen und die wichtigste Stadt von {link:zephras-isle}Zephras Isle{/link}, erbaut am südöstlichen Rand der Insel. Der Hochälteste {link:talaanis-shadowsong}Talaanis Shadowsong{/link} hält hier Rat, und {link:valennia-stormfist}Valennia Stormfist{/link} befehligt die {link:peacekeepers}Peacekeepers{/link} aus derselben Halle. Die {link:windshapers}Windshapers{/link} unterhalten eine Loge nahe der Stadtmitte, und der {link:high-order}High Order{/link} eine weitere an ihrem äußersten südöstlichen Rand. Die Hauptfrau verbietet offenen Streit zwischen ihnen in ihren Straßen. Flüchtlinge aus {link:ruins-of-ban-aethal}Ban'aethal{/link} warten in der Stadt auf Nachricht. Von den Valanaar Skydocks segeln nun die Skycutter-Schiffe über die Ebenen nach {link:azeroth}Azeroth{/link}: eines mit Kurs auf {link:mulgore}Mulgore{/link}, das andere auf {link:dalaran}Dalaran{/link}.]=],
		},
	},
})

Translate("deDE", "gustberry-lowlands", {
	title = "Gustberry Lowlands",
	aliases = { "Gustberry Fields" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Gustberry Lowlands sind das Ackerland rund um {link:valanaar}Valanaar{/link}, reich an Obstgärten und offenen Feldern. Riesige Flutterflies treiben über sie hinweg, und Galestriders plündern die Ernte. Räuberische Wegelagerer unterhalten kleine Lager in den Hügeln. Die Shrieklings einer Höhle westlich der Stadt sind dreist geworden, und ein Gelehrter des {link:high-order}High Order{/link} wäre unter ihnen beinahe gestorben. Als die {link:al-aketh}Al'Aketh{/link} gegen den östlichen Pylon zogen, wurde das Tiefland zum Schlachtfeld, und Heiler und Schläger des Kults füllten die Felder nördlich der Stadt. Am Rand der Insel westlich von Valanaar unterhalten die {link:windshapers}Windshapers{/link} einen verborgenen Shrine of Flames.]=],
		},
	},
})

Translate("deDE", "east-pylon-watchtower", {
	title = "East Pylon Watchtower",
	aliases = { "östlicher Wachturm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der East Pylon Watchtower steht unmittelbar vor {link:valanaar}Valanaar{/link} und bewacht den {link:anchor-pylons}Ankerpylon{/link}, der der Stadt am nächsten ist. Die {link:al-aketh}Al'Aketh{/link} griffen ihn mit großer Macht an, angeführt von {link:commander-belguilos}Kommandantin Belguilos{/link}, einer einstigen Peacekeeperin, die der Kult die Brecherin nennt. {link:yorana-windyreed}Yorana Windyreed{/link} brachte eine Entsatztruppe aus der Stadt und hielt stand, obwohl sie erwartete, dort zu sterben. Als Belguilos fiel, brach der Angriff zusammen. Der Rat sah, dass der Kult den westlichen und den östlichen Turm gleichermaßen angegriffen hatte, und begriff endlich, dass sein Ziel die Pylonen selbst waren.]=],
		},
	},
})

Translate("deDE", "windfield-orchard", {
	title = "Windfield Orchard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im Windfield Orchard wachsen Stormapples, im Tiefland westlich von {link:valanaar}Valanaar{/link}. Er gehört Alvarion und {link:aamelia-windfield}Aamelia Windfield{/link}. Eine Räuberbande unter Ferauu the Bludgeon nahm sich mit Gewalt einen Anteil jeder Ernte. Als Alvarion schwer verwundet wurde, ging er in die Stadt, um Hilfe anzuwerben, während seine Frau blieb, um ihre Bäume zu verteidigen. Im Obstgarten steht auch ein altes Zyklonkonstrukt der {link:vanishing-of-the-wind-spirits}Windgeister{/link}, zerbrochen und murmelnd. Es stellt immer wieder dieselbe Frage: Was ist sein Zweck?]=],
		},
	},
})

Translate("deDE", "shrine-of-akir", {
	title = "Shrine of Akir",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Shrine of Akir erhebt sich nördlich von {link:valanaar}Valanaar{/link} über die Felder und Fälle der östlichen Insel. Er ist die Festung der {link:al-aketh}Al'Aketh{/link} und der Sitz der {link:high-priestess-lorthuna}Hohepriesterin Lorthuna{/link}. Hierher kam der Magister des {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link}, um vom Frieden zu sprechen, und hier starb er. Hier führte auch {link:valennia-stormfist}Valennia Stormfist{/link} die {link:peacekeepers}Peacekeepers{/link}, die {link:windshapers}Windshapers{/link} und den High Order in ihren Sturmangriff. Ihre Kämpfer griffen die Front an, während sie die Orden die Flanke hinauf und in das innere Heiligtum führte. Viele fielen auf beiden Seiten. Lorthuna floh durch ein Portal zu den Spitzen darüber.]=],
		},
	},
})

Translate("deDE", "rohashi-spires", {
	title = "Rohashi Spires",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Rohashi Spires schweben im offenen Himmel über dem {link:shrine-of-akir}Shrine of Akir{/link} und sind nur durch ein Portal vom Schrein aus zu erreichen. Hier leistete {link:high-priestess-lorthuna}Lorthuna{/link} ihren letzten Widerstand. Sie war nicht gekommen, um die Schutzbanne zu brechen, denn diese waren bereits gebrochen. Sie war gekommen, um ein Leuchtfeuer zu entzünden. Beantwortet wurde es von {link:rohash}Rohash{/link}, dem Fürsten des Ostwinds. Einen Augenblick lang standen die Elfen allein gegen das Heer des Windfürsten. Dann kamen die Schamanen des {link:earthen-ring}Irdenen Rings{/link} und die Magier der {link:kirin-tor}Kirin Tor{/link} hindurch, und die Spitzen wurden zu dem Ort, an dem die {link:skyborne}Skyborne{/link} ihren neuen Verbündeten zum ersten Mal begegneten.]=],
		},
	},
})

Translate("deDE", "shadowgale-forest", {
	title = "Shadowgale Forest",
	aliases = { "Shadowgale" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Shadowgale Forest bedeckt den Nordosten von {link:zephras-isle}Zephras{/link}, und die meisten {link:skyborne}shen'dorei{/link} halten ihn für verwunschen. Sie irren sich nicht. Bleiche {link:vanishing-of-the-wind-spirits}Windgeister{/link}, die man Hollows nennt, treiben zwischen seinen Bäumen, und sie erschienen zum ersten Mal, nachdem die Windgeister verschwunden waren. Der Kult meidet den Wald gewöhnlich, eine Furcht, die seine Druiden gern nähren. In einer Höhle im Nordosten haben die Nightclaw-Druiden ihren Bau. Die {link:al-aketh}Al'Aketh{/link} fielen ohne Vorwarnung darüber her, geführt von einem der eigenen Druiden. Zwischen den Bäumen lebt auch ein Einsiedler, der seit Jahren mit niemandem gesprochen hat.]=],
		},
	},
})

Translate("deDE", "ruins-of-ban-aethal", {
	title = "Ruins of Ban'aethal",
	aliases = { "Ban'aethal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ban'aethal war ein Dorf tief im {link:shadowgale-forest}Shadowgale Forest{/link}, am nordöstlichen Rand der Insel. Eines Nachts begann ohne Vorwarnung der Boden darunter in den Himmel zu stürzen. Seine Bewohner flohen mit dem, was sie tragen konnten, und warten nun in {link:valanaar}Valanaar{/link}. Einige gingen zurück, um ihre Habe zu holen, und kehrten nicht wieder. Zwischen den Ruinen sammeln sich geisterhafte Wesen und singen ein seltsames, trauriges Lied, als wären sie an diesen Ort gebunden. Es heißt, dass dort ein großer Elementardrache schläft.]=],
		},
	},
})

Translate("deDE", "talaanis-shadowsong", {
	title = "Talaanis Shadowsong",
	subtitle = "Hochältester von Zephras Isle",
	found = "Die Ratshalle von Valanaar",
	hint = "Sucht den Hochältesten in der Ratshalle von Valanaar auf.",
	allegiance = "Ältestenrat · Zephras Isle",
	aliases = { "Hochältester Shadowsong" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Talaanis Shadowsong ist der Hochälteste von {link:zephras-isle}Zephras Isle{/link} und das Oberhaupt seines Ältestenrats. Er regiert von {link:valanaar}Valanaar{/link} aus, an der Seite der Hauptfrau der {link:peacekeepers}Peacekeepers{/link}. Er gehört weder den {link:windshapers}Windshapers{/link} noch dem {link:high-order}High Order{/link} an, und er muss ein Volk zusammenhalten, das bereit ist, sich selbst zu zerreißen. Die ihm dienen, nennen ihn einen guten Mann. Selbst in diesen harten Jahren liebt ihn das Volk der Insel.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Talaanis steht an der Spitze der alten Ordnung, die der {link:flight-from-eldre-thalas}Shal'nan{/link} hinterließ: eines Rates, den die {link:skyborne}shen'dorei{/link} selbst wählen. In seiner Zeit wurde diese Ordnung geprüft wie nie zuvor. Die Geister sind fort, die Pylonen versagen, ein Kult des Windfürsten hält die halbe Insel, und die beiden großen Orden seines Volkes sprechen kaum miteinander. In seiner Halle wurde das wahre Ziel des Kults aufgedeckt, und sein Segen schickte die Jungen von {link:zephras-isle}Zephras{/link} hinab nach {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt den Ältestenrat von {link:valanaar}Valanaar{/link} aus.
• Er gab den {link:peacekeepers}Peacekeepers{/link} eine Spur zum Kult weiter: einen Überläufer der {link:al-aketh}Al'Aketh{/link}, der die Seiten wechseln wollte.
• Er hörte den Erinnerungskristall, der Lorthunas Plan enthüllte.
• Er segnete die Expeditionen beider Orden nach {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Talaanis' Leben vor diesen Tagen ist wenig geschrieben. Keine Chronik verzeichnet, wie lange er schon Hochältester ist oder wer sein Neffe war.]=],
		},
	},
	chapters = {
		{
			title = "Der Siegelring der Shadowsong",
			hint = "Bringt dem Hochältesten Nachricht vom westlichen Wachturm.",
			text = [=[Die Verteidiger des westlichen Wachturms starben auf ihrem Posten. Unter den Toten war der Neffe des Hochältesten, und sein Familiensiegelring kehrte in der Hand eines Fremden nach {link:valanaar}Valanaar{/link} zurück. Talaanis nahm den Ring und die Nachricht mit Würde entgegen. Dann tat er, was ein Ältester in solchen Tagen tun muss. Er schickte den Überbringer zu den {link:peacekeepers}Peacekeepers{/link}, denn die Insel brauchte jedes willige Schwert.]=],
		},
		{
			title = "Der Erinnerungskristall",
			hint = "Bringt dem Hochältesten, was der Überläufer bei sich trug.",
			text = [=[Der Überläufer starb, bevor er sprechen konnte, doch unter seinem Leichnam lag ein beschädigter Erinnerungskristall. Talaanis ließ {link:valennia-stormfist}Valennia{/link} ihn erwecken. Gebrochene Stimmen trieben daraus hervor: {link:high-priestess-lorthuna}Lorthuna{/link}, die von den Pylonen sprach und von Schutzbannen, die fallen müssten. Valennia erinnerte sich, dass der {link:flight-from-eldre-thalas}Shal'nan{/link} einst gesagt hatte, die Pylonen seien Schutzbanne ebenso wie Anker, Schilde gegen alles andere, was in {link:skywall}Skywall{/link} hauste. Talaanis begriff sofort. Der Kult wollte die Insel seinem Windfürsten öffnen.]=],
		},
		{
			title = "Das Schicksal von Zephras",
			hint = [=[Berichtet dem Hochältesten, was auf den Spitzen in Erfahrung gebracht wurde.]=],
			text = [=[Nach den Spitzen kamen die Anführer beider Orden mit derselben düsteren Nachricht zu Talaanis. Die Schutzbanne waren fort, und die Insel lag {link:al-akir}Al'Akir{/link} in seinem eigenen Reich offen. Jeder Orden wollte seine Antwort in {link:azeroth}Azeroth{/link} suchen, und Talaanis gab beiden seinen Segen. Er hoffte, dass das, was sie fanden, {link:zephras-isle}Zephras{/link} die Beständigkeit bringen würde, die ihm seit Jahren fehlte.]=],
		},
	},
	mentions = {
		{ text = "Die Bitte des Hochältesten" },
		{ text = "Der Überläufer" },
		{ text = "Unglückliche Nachrichten" },
		{ text = "Verzweifelte Zeiten" },
		{
			text = [=[Was als Nächstes kommt, der Abschied der {link:horde}Horde{/link}]=],
		},
		{
			text = [=[Was als Nächstes kommt, der Abschied der {link:alliance}Allianz{/link}]=],
		},
	},
	bonds = {
		{ id = "valennia-stormfist", name = "Valennia Stormfist", note = "Hauptfrau seiner Peacekeepers" },
		{ id = "aetheen-of-the-gales", name = "Aetheen of the Gales", note = "aus demselben Rat" },
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "Große Himmelsseherin der Windshapers" },
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "Obermagister des High Order" },
		{ id = "high-priestess-lorthuna", name = "Hohepriesterin Lorthuna", note = "wollte seine Insel dem Windfürsten öffnen" },
	},
})

Translate("deDE", "elaadrin-evengale", {
	title = "Elaadrin Evengale",
	subtitle = "Obermagister des High Order",
	found = "Die Loge des High Order, im Südosten Valanaars",
	hint = [=[Sucht den Obermagister in der Loge des High Order am Rand von Valanaar auf.]=],
	allegiance = "High Order · Allianz",
	aliases = { "Elaadrin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Elaadrin Evengale ist der Obermagister des {link:high-order}High Order{/link}, der Magister hochgeborenen Blutes auf {link:zephras-isle}Zephras Isle{/link}. Von seiner Loge in {link:valanaar}Valanaar{/link} aus führt er jene, die glauben, dass die {link:skyborne}shen'dorei{/link} ihren elementaren Schutzherren zu sehr vertrauten. Er ist stolz, scharfzüngig und seines Weges gewiss. Unter seiner Führung hat der High Order einen Weg durch die Ebenen nach {link:azeroth}Azeroth{/link} gefunden, und dort einen neuen Verbündeten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Elaadrin glaubt, dass die Gaben der verschwundenen Geister durch die alte Magie der {red:highborne}Hochgeborenen{/red} aufgewogen werden können, wenn sein Volk sie nur wieder erlernt. Diese Magie ist in {link:skywall}Skywall{/link} schwach geworden. Also blickte er nach außen. Seine Magister schnitten eine Art Schlüsselloch durch die Ebenen und spähten auf die Welt, die ihre Vorfahren verlassen hatten, und jemand auf der anderen Seite blickte zurück: die {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link}. Durch ihn hat sich der {link:high-order}High Order{/link} der {link:alliance}Allianz{/link} angeschlossen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt den {link:high-order}High Order{/link} von dessen Loge in {link:valanaar}Valanaar{/link} aus.
• Er schickte den Magister {link:belathaan-brightwish}Belathaan Brightwish{/link} zum {link:shrine-of-akir}Shrine of Akir{/link}, um Frieden mit dem Kult zu suchen.
• Er erforschte die Magie der heiligen Steine der {link:windshapers}Windshapers{/link} gegen deren Willen.
• Er rief nach den {link:kirin-tor}Kirin Tor{/link}, als der Sturm auf den Schrein geplant wurde.
• Er stand an der Seite {link:ayessa-dawnsinger}Ayessa{/link} Dawnsingers gegen {link:high-priestess-lorthuna}Lorthuna{/link} auf den {link:rohashi-spires}Rohashi Spires{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Das Schlüsselloch",
			hint = "Hört die Pläne des Obermagisters für den High Order.",
			text = [=[Elaadrin erzählte den Jungen seines Ordens, was das Schlüsselloch ihm gezeigt hatte. Das Land, aus dem sein Volk geflohen war, war nur ein Teil einer riesigen Welt, die nun {link:azeroth}Azeroth{/link} hieß. Seine Magier hatten dort Freunde gefunden, einen Orden, dem eigenen sehr ähnlich. Einige {link:skyborne}shen'dorei{/link}, sagte er, müssten {link:skywall}Skywall{/link} verlassen, zurückgewinnen, was ihre Vorfahren verloren hatten, und es heimbringen, um die Insel zu retten.]=],
		},
		{
			title = "Die versilberte Zunge",
			hint = [=[Antwortet dem Obermagister, nachdem das Schicksal seines Gesandten bekannt ist.]=],
			text = [=[Als der Kult zum ersten Mal zur Gewalt griff, hatte Elaadrin zu Verhandlungen geraten. Er schickte seinen Freund {link:belathaan-brightwish}Belathaan{/link} zum Schrein. Nach {link:valanaar}Valanaar{/link} kam eine Schachtel zurück, die Belathaans Zunge enthielt, mit Silber bemalt. Elaadrin wollte keine Gespräche mehr. Er bot den {link:peacekeepers}Peacekeepers{/link} die volle Unterstützung des {link:high-order}High Order{/link} an.]=],
		},
		{
			title = "Im Auge des Sturms",
			hint = "Steht dem Obermagister auf den Spitzen über dem Schrein bei.",
			text = [=[Auf den Spitzen bot Elaadrin {link:high-priestess-lorthuna}Lorthuna{/link} einen schnellen Tod an, wenn sie sich ergäbe. Sie lachte ihn aus. Als der Diener des Windfürsten kam, hatte Elaadrin ihm wenig mehr entgegenzusetzen als seinen Mut, bis die Magier der {link:kirin-tor}Kirin Tor{/link} eintrafen und er Erzmagier {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} zum ersten Mal begrüßte.]=],
		},
		{
			title = "Der Skycutter nach Dalaran",
			hint = "Nehmt von Valanaar aus ein Schiff in die Stadt der Magier.",
			text = [=[Elaadrin hatte als Erster seines Volkes {link:azeroth}Azeroth{/link} betreten wollen. Der Kult durchkreuzte seine Pläne. Vorerst bleibt er in {link:valanaar}Valanaar{/link}, und er schickt die jungen Magister voraus nach {link:dalaran}Dalaran{/link}, wo einer seiner Magier darauf wartet, sie zu empfangen.]=],
		},
	},
	mentions = {
		{ text = "Der Obermagister" },
		{ text = "Den Wind einfangen" },
		{ text = "Im Dienste von {link:zephras-isle}Zephras{/link}" },
		{ text = "Fillions Auftrag" },
		{ text = "Das Schicksal von {link:zephras-isle}Zephras{/link}" },
		{ text = "Was als Nächstes kommt" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "seine Rivalin, vorerst seine Verbündete" },
		{ id = "belathaan-brightwish", name = "Belathaan Brightwish", note = "sein Freund und Gesandter" },
		{ id = "rathiril-sunlance", name = "Rathiril Sunlance", note = "Ältester seines Ordens in Shen'dar" },
		{ id = "valennia-stormfist", name = "Valennia Stormfist", note = "die Hauptfrau, der zu folgen er einwilligte" },
		{ id = "high-priestess-lorthuna", name = "Hohepriesterin Lorthuna", note = "die Priesterin, die er auf den Spitzen bekämpfte" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Hochältester von Zephras Isle" },
	},
})

Translate("deDE", "ayessa-dawnsinger", {
	title = "Ayessa Dawnsinger",
	subtitle = "Große Himmelsseherin der Windshapers",
	found = "Die Loge der Windshapers, im Zentrum Valanaars",
	hint = [=[Sucht die Große Himmelsseherin in der Loge der Windshapers in Valanaar auf.]=],
	allegiance = "Windshapers · Horde",
	aliases = { "Ayessa", "Große Himmelsseherin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ayessa Dawnsinger ist die Große Himmelsseherin der {link:windshapers}Windshapers{/link}, der Schamanen und Seher von {link:zephras-isle}Zephras Isle{/link}. Sie ist feurig, stolz und schnell erzürnt, und sie wacht eifersüchtig über ihren Titel und die heiligen Stätten ihres Ordens. Sie glaubt, dass ihr Volk seine verlorenen Geister heimrufen muss, und auf der Suche nach ihnen fand sie den {link:earthen-ring}Irdenen Ring{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ayessa ist die Stimme jener {link:skyborne}shen'dorei{/link}, die den Windgeistern noch die Treue halten. Sie leugnet die Krise nicht. Sie sagt offen, dass die {link:windshapers}Windshapers{/link} vielleicht eine Mitschuld am Fortgang der Geister tragen, und sie nennt die {link:al-aketh}Al'Aketh{/link} ein dunkles Spiegelbild ihres eigenen Ordens. Als sie mit ihrer Himmelssicht die Ebenen durchsuchte, stieß sie auf Schamanen {link:azeroth}Azeroth{/link}s, deren Blick über die Himmel hinausreichte. Durch {link:muln-earthfury}Muln Earthfury{/link} kamen die Windshapers zum Ring, und durch den Ring zur {link:horde}Horde{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie führt die {link:windshapers}Windshapers{/link} von deren Loge in {link:valanaar}Valanaar{/link} aus.
• Sie schickte eine Novizin, um den Magister des {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan{/link} dafür zu bestrafen, dass er sich an den Konstrukten der Geister zu schaffen machte.
• Sie fordert Blut für Blut, wenn Windshapers erschlagen werden.
• Sie rief vor dem Sturm auf den Schrein nach dem Irdenen Ring.
• Sie stellte {link:high-priestess-lorthuna}Lorthuna{/link}, einst ihre Schwester im Orden, auf den {link:rohashi-spires}Rohashi Spires{/link} zur Rede.]=],
		},
	},
	chapters = {
		{
			title = "Ein großes Abenteuer",
			hint = "Hört den Plan der Großen Himmelsseherin für die Windshapers.",
			text = [=[Ayessa erzählte den jungen {link:windshapers}Windshapers{/link}, was sie gefunden hatte. Die Wiege ihres Volkes, {link:kalimdor}Kalimdor{/link}, war nun Teil einer weit größeren Welt. Deren Schamanen waren mächtiger als alle auf {link:zephras-isle}Zephras{/link}, und ihr Wissen um die Ebenen könnte die Insel retten. Sie bat starke junge {link:skyborne}shen'dorei{/link}, sich einer Expedition zu ihnen anzuschließen.]=],
		},
		{
			title = "Das zerbrochene Konstrukt",
			hint = [=[Findet heraus, wer die Teile des Konstrukts von Valanaar gestohlen hat.]=],
			text = [=[Eines der letzten funktionierenden Konstrukte in {link:valanaar}Valanaar{/link} wurde seiner Bauteile beraubt aufgefunden. Die Spur führte zum Magister des {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link}. Für Ayessa war es der Beweis für den Hochmut, den sie den Magistern schon lange vorwarf. Sie ließ ausrichten, dass sie auf die Drohungen des High Order erst antworten werde, wenn dessen Anführer persönlich zu ihr komme.]=],
		},
		{
			title = "Meine einstige Schwester",
			hint = [=[Steht der Großen Himmelsseherin auf den Spitzen über dem Schrein bei.]=],
			text = [=[Auf den Spitzen flehte Ayessa {link:high-priestess-lorthuna}Lorthuna{/link} an, aufzuhören, und warnte, dass das Brechen der Schutzbanne sie alle verderben könnte. Lorthuna verspottete sie als gefallene Schwester, die sich mit dem {link:high-order}High Order{/link} abgab. Als der Fürst des Ostwinds kam, traf {link:muln-earthfury}Muln Earthfury{/link} mit den Schamanen des Rings ein. Ayessa begegnete ihm zum ersten Mal mitten in einer Schlacht.]=],
		},
		{
			title = "Die Vorhut",
			hint = [=[Nehmt von Valanaar aus ein Schiff in das Land des Irdenen Rings.]=],
			text = [=[Ayessa hatte selbst nach {link:azeroth}Azeroth{/link} gehen wollen. Der Kult hielt sie in {link:valanaar}Valanaar{/link} fest. Stattdessen schickt sie eine Handvoll junger {link:windshapers}Windshapers{/link} als ihre Vorhut voraus, nach {link:mulgore}Mulgore{/link}, wo {link:alaana-stormwalker}Alaana Stormwalker{/link} wartet. Sie hat geschworen, dass ihr Volk einen Weg finden wird, seine Heimat zu retten.]=],
		},
	},
	mentions = {
		{ text = "Die Große Himmelsseherin" },
		{ text = "Eine entschlossene Antwort" },
		{ text = "Blut für Blut" },
		{ text = "Im Dienste von {link:zephras-isle}Zephras{/link}" },
		{ text = "Das Schicksal von {link:zephras-isle}Zephras{/link}" },
		{ text = "Was als Nächstes kommt" },
	},
	bonds = {
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "Schamane des Irdenen Rings, der ihr antwortete" },
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "ihr Rivale, vorerst ihr Verbündeter" },
		{ id = "high-priestess-lorthuna", name = "Hohepriesterin Lorthuna", note = "einst ihre Schwester bei den Windshapers" },
		{ id = "illaya-amberwind", name = "Illaya Amberwind", note = "Älteste ihres Ordens in Shen'dar" },
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "erwartet ihre Vorhut in Mulgore" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Hochältester von Zephras Isle" },
	},
})

Translate("deDE", "al-akir", {
	title = "Al'Akir",
	subtitle = "Der Windfürst, Herr von Skywall",
	found = "Irgendwo in den endlosen Stürmen von Skywall",
	allegiance = "Die Elementarebene",
	aliases = { "Al'Akir der Windfürst", "Windfürst" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Al'Akir der Windfürst ist der Herr der Luft und der Gebieter von {link:skywall}Skywall{/link}. Er ist einer der vier großen Elementarfürsten, ebenbürtig mit Ragnaros des Feuers, Neptulon der Gezeiten und Therazane des Steins. Wind und Sturm sind seine Diener, und die Elementare der Luft sind sein Heer. Keine Chronik der Sterblichen erzählt von jemandem, der vor ihm stand und zurückkehrte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Für die {link:elements}Elementarfürsten{/link} zählen sterbliche Völker wenig. Der Windfürst wusste nicht, dass es die {link:skyborne}shen'dorei{/link} gab. Zehntausend Jahre lang verbargen Geister seines eigenen Reiches {link:zephras-isle}Zephras Isle{/link} hinter den Schutzbannen ihrer Pylonen vor seinem Blick, und die Elfen wuchsen in seiner Domäne auf, ohne ihn zu kennen. Die Geister, die sie großzogen, wollten seinen Namen nicht aussprechen. Wenn die Elfen fragten, wurden die Geister unruhig, wichen der Frage aus und sagten ihnen, sie hätten auf ihren Inseln nichts zu fürchten. Manche shen'dorei begannen zu bezweifeln, dass es ihn gab. Andere, die mit ihrer Himmelssicht über die Ebene blickten, erhaschten einen Blick auf seine Macht und begannen, sie anzubeten.]=],
		},
		{
			title = "Taten",
			text = [=[• Im ersten Zeitalter der Welt dienten er und die anderen Elementarfürsten den Alten Göttern, bis die Diener der Titanen die Elementare in einem abgesonderten Reich banden.
• Er beherrscht {link:skywall}Skywall{/link} mit einem Heer von Luftelementaren und Fürsten der Winde.
• Sein Name wird von den {link:al-aketh}Al'Aketh{/link} angebetet, die sich seine Gläubigen nennen.
• Seine Missionare warnen, dass jeder, der unter falschem Vorwand zu seinen Gläubigen kommt, seinen Zorn spüren wird.
• Sein Diener {link:rohash}Rohash{/link} prahlt, dass die Heere des Windfürsten in Skywall kein Ende haben.
• Die Furcht vor seinem Kommen treibt nun beide Orden der {link:skyborne}shen'dorei{/link} dazu, in {link:azeroth}Azeroth{/link} Hilfe zu suchen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieses Zeitalters beschreibt das Antlitz des Windfürsten, seinen Sitz in {link:skywall}Skywall{/link} oder seinen Willen. Die {link:skyborne}shen'dorei{/link} kennen ihn nur durch das Schweigen ihrer Geister und die Prahlereien seiner Diener.]=],
		},
	},
	chapters = {
		{
			title = "Der Blick des Windfürsten",
			hint = [=[Erfahrt, was der Irdene Ring und die Kirin Tor den Orden über den Windfürsten erzählten.]=],
			text = [=[Als {link:high-priestess-lorthuna}Lorthuna{/link} ihr Leuchtfeuer auf den {link:rohashi-spires}Rohashi Spires{/link} entzündete, antwortete {link:rohash}Rohash{/link}, der Fürst des Ostwinds. Er staunte, dass ein solcher Ort im Reich des Windfürsten bestehen konnte, und er lobte seine „abtrünnigen Brüder“ dafür, dass sie ihn so gut verborgen hatten. Er versprach, dass sein Herr davon erfahren werde. Die Schamanen des Irdenen Rings und die Magier der {link:kirin-tor}Kirin Tor{/link} erzählten den Elfen, was sie über die Elementarfürsten wussten. Was sie hörten, gab den Anführern beider Orden guten Grund zur Furcht. In seiner eigenen Domäne konnte Al'Akir sie vernichten, wann immer er wollte.]=],
		},
	},
	mentions = {
		{
			text = [=[Der nächste Schritt, wo eine Älteste ihn den angeblichen Herrscher von {link:skywall}Skywall{/link} nennt]=],
		},
		{
			text = [=[{link:falaath-village}Falaath Village{/link}, der Ruf des Kults, ihm zu dienen]=],
		},
	},
	bonds = {
		{ id = "rohash", name = "Rohash", note = "Fürst des Ostwinds, sein Diener" },
		{ id = "high-priestess-lorthuna", name = "Hohepriesterin Lorthuna", note = "entzündete in seinem Namen ein Leuchtfeuer" },
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "fürchtet sein Urteil" },
	},
})

Translate("deDE", "valennia-stormfist", {
	title = "Valennia Stormfist",
	subtitle = "Hauptfrau der Peacekeepers",
	found = "Die Ratshalle von Valanaar",
	hint = [=[Sucht die Hauptfrau der Peacekeepers in der Ratshalle von Valanaar auf.]=],
	allegiance = "Peacekeepers · Zephras Isle",
	aliases = { "Valennia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Valennia Stormfist ist die Hauptfrau der {link:peacekeepers}Peacekeepers{/link}, der Miliz von {link:zephras-isle}Zephras Isle{/link}. Sie hält Ordnung in {link:valanaar}Valanaar{/link} und verbietet den {link:windshapers}Windshapers{/link} und dem {link:high-order}High Order{/link}, in ihren Straßen zu kämpfen. Sie ist geradeheraus und praktisch. Lange Zeit mieden ihre Peacekeepers den offenen Krieg mit dem Kult. Als das nicht mehr möglich war, wurde sie diejenige, die den Krieg plante.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Valennia steht zwischen den beiden zerstrittenen Orden der Insel und dem Kult, der sie beide bedroht. Sie sah, dass die {link:windshapers}Windshapers{/link} und der {link:high-order}High Order{/link} sich niemals füreinander vereinen würden. Gegen einen größeren Feind könnten sie sich vereinen. Ihr Plan für den Sturm auf den {link:shrine-of-akir}Shrine of Akir{/link}, lange vorbereitet, bevor er gebraucht wurde, brachte alle drei Kräfte gemeinsam ins Feld.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie befehligt die {link:peacekeepers}Peacekeepers{/link} von {link:valanaar}Valanaar{/link} aus.
• Sie schickte Entsatz zum östlichen Wachturm, als der Kult ihn angriff.
• Sie erweckte den Erinnerungskristall des Überläufers und erinnerte sich, dass die Pylonen auch Schutzbanne waren.
• Sie gewann die Unterstützung beider Orden für den Sturm auf den Schrein.
• Sie drang in das innere Heiligtum des {link:shrine-of-akir}Shrine of Akir{/link} ein.]=],
		},
	},
	chapters = {
		{
			title = "Verzweifelte Zeiten",
			hint = [=[Überbringt den Plan der Hauptfrau den Anführern beider Orden.]=],
			text = [=[Der Kult beherrschte einen großen Teil der Insel und hielt die {link:peacekeepers}Peacekeepers{/link} für geschlagen. Valennia wollte diesen Hochmut gegen ihn wenden. Ein Ablenkungsangriff an der Front des Schreins und eine kleine Truppe aus Peacekeepers, {link:windshapers}Windshapers{/link} und Magistern die Flanke hinauf könnten das innere Heiligtum erreichen und {link:high-priestess-lorthuna}Lorthuna{/link} dort ein Ende bereiten. Beide Orden stimmten zu. Keiner vergab dem anderen.]=],
		},
		{
			title = "Das innere Heiligtum",
			hint = "Folgt den Truppen der Hauptfrau in das Herz des Schreins.",
			text = [=[Der Kampf im Heiligtum war heftig und dann seltsam still. Valennias Truppen hielten es, verwundet und ausgedünnt. {link:high-priestess-lorthuna}Lorthuna{/link} war durch ein Portal zu den Spitzen darüber geflohen, und die Anführer beider Orden folgten ihr. Valennia, zu schwer verletzt, um mitzugehen, schickte andere, um ihnen zu helfen.]=],
		},
	},
	mentions = {
		{ text = "Nach {link:valanaar}Valanaar{/link}" },
		{ text = "Turmverteidigung" },
		{ text = "Verwanzt" },
		{ text = "Bereitet euch auf die Schlacht vor" },
		{
			text = [=[Stellt {link:high-priestess-lorthuna}Lorthuna{/link} zur Rede]=],
		},
	},
	bonds = {
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "der Hochälteste, dem sie dient" },
		{ id = "constable-aonda", name = "Konstablerin Aonda", note = "wahrt den Frieden in Shen'dar" },
		{ id = "yorana-windyreed", name = "Yorana Windyreed", note = "ihre Leutnantin" },
		{ id = "hyusaa-quickbreeze", name = "Hyusaa Quickbreeze", note = "ihre Stellvertreterin am Schrein" },
		{ id = "high-priestess-lorthuna", name = "Hohepriesterin Lorthuna", note = "die Feindin, die sie jagte" },
	},
})

Translate("deDE", "aetheen-of-the-gales", {
	title = "Aetheen of the Gales",
	subtitle = "Älteste von Zephras Isle",
	found = "Thendal Village",
	hint = [=[Sucht die Älteste des Rates auf, die in Thendal Village über die Jungen wacht.]=],
	allegiance = "Ältestenrat · Zephras Isle",
	aliases = { "Aetheen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aetheen of the Gales ist ein Mitglied des Ältestenrats von {link:zephras-isle}Zephras Isle{/link}. Sie ist nach {link:thendal-village}Thendal Village{/link} gekommen, um den Fluss der Winde im Hain zu lesen und die jungen {link:skyborne}shen'dorei{/link} zu prüfen, die dort mündig werden. Sie beobachtet, bevor sie spricht. Wenn ein Jugendlicher ihr begegnet, weiß sie bereits viel über ihn.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Aetheen ist das Auge des Rates auf die nächste Generation. In einer Zeit, in der die Insel jede fähige Hand braucht, entscheidet sie, welche der Jungen bereit sind, den Schutz des Hains zu verlassen. Sie gehört auch zu den Ersten, die ihnen die Gefahr offen beim Namen nennen: die {link:al-aketh}Al'Aketh{/link}, Eiferer eines „angeblichen“ Herrschers von {link:skywall}Skywall{/link}, deren Macht und Ehrgeiz jeden Tag wachsen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie liest für den Rat die Winde von {link:thendal-village}Thendal Grove{/link}.
• Sie prüft die Jungen, indem sie sie gegen die Ursera und deren Baumutter schickt.
• Sie schickt sie nach Süden zu {link:constable-aonda}Konstablerin Aonda{/link} in {link:shen-dar-village}Shen'dar Village{/link}, das der Kult bedroht.
• Sie schickt andere zu einem Wanderer bei Shen'dar, damit sie die Wege der Wildnis lernen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Aetheens Leben vor diesen Tagen ist wenig geschrieben. Es ist nicht verzeichnet, ob sie einem der Orden angehört oder wie lange sie schon im Rat sitzt.]=],
		},
	},
	chapters = {
		{
			title = "Der nächste Schritt",
			hint = [=[Besteht die Prüfung der Ältesten und geht, wohin sie Euch schickt.]=],
			text = [=[In den Höhlen südlich des Hains waren die Ursera hungrig und verzweifelt geworden, angeführt von einer Baumutter, die die Waldläufer Urs'anah nannten. Aetheen schickte die Jugend dorthin, als Prüfung ihrer Entschlossenheit. Als die Prüfung bestanden war, lobte sie sie nicht lange. Sie schickte sie nach Süden, wo der Kult {link:shen-dar-village}Shen'dar Village{/link} bedrängte, und trug ihnen auf zu sagen, dass sie sie geschickt habe.]=],
		},
	},
	mentions = {
		{ text = "Aetheen of the Gales" },
		{ text = "Üble Matriarchin" },
		{ text = "Der Abenteurer" },
	},
	bonds = {
		{ id = "rorian-the-dayseeker", name = "Rorian the Dayseeker", note = "schickt die Jungen zu ihr" },
		{ id = "constable-aonda", name = "Konstablerin Aonda", note = "nach ihren Worten eine gute Frau" },
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Hochältester ihres Rates" },
	},
})

Translate("deDE", "high-priestess-lorthuna", {
	title = "Hohepriesterin Lorthuna",
	subtitle = "Hohepriesterin der Al'Aketh",
	found = "Der Shrine of Akir und die Spitzen darüber",
	hint = "Stellt Euch der Hohepriesterin des Kults des Windfürsten.",
	allegiance = "Al'Aketh",
	aliases = { "Lorthuna" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hohepriesterin Lorthuna führt die {link:al-aketh}Al'Aketh{/link}, den Kult des {link:al-akir}Al'Akir{/link} auf {link:zephras-isle}Zephras Isle{/link}. Einst war sie eine {link:windshapers}Windshaper{/link} und eine Schwester in {link:ayessa-dawnsinger}Ayessa{/link} Dawnsingers Orden. Nun herrscht sie über den {link:shrine-of-akir}Shrine of Akir{/link} und spricht von einem großen Werk, das den Windfürsten zu ihrem Volk bringen wird. Sie ist kalt, klug und grausam, und ihre Anhänger nennen sich die Werkzeuge ihres Willens.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lorthuna sah, was der Rest ihres Volkes nicht sah: dass die Pylonen von {link:zephras-isle}Zephras{/link} Schutzbanne ebenso wie Anker waren. Sie machte dieses Geheimnis zur Waffe. Ihr Kult nahm {link:falaath-village}Falaath Village{/link} ein, griff {link:morgan-s-vigil}die Wacht{/link}ürme der Pylonen an und brachte die Schutzbanne zu Fall. Was auch immer aus ihr wurde, ihr Werk lässt sich nicht ungeschehen machen. Zephras liegt nun offen vor seinem Windfürsten.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickte vom {link:shrine-of-akir}Shrine of Akir{/link} aus Plünderer und Prediger über die Insel.
• Sie traf {link:skypriest-aanders}Himmelspriester Aanders{/link} in Falaath und setzte ihre Angriffe auf Shen'dar und den westlichen Wachturm in Gang.
• Sie ließ den Gesandten des {link:high-order}High Order{/link} {link:belathaan-brightwish}Belathaan Brightwish{/link} töten und schickte seine Zunge nach {link:valanaar}Valanaar{/link} zurück.
• Sie entzündete auf den {link:rohashi-spires}Rohashi Spires{/link} ein Leuchtfeuer für die Diener des Windfürsten.]=],
		},
	},
	chapters = {
		{
			title = "Der Gast in Falaath",
			hint = "Erfahrt, was der Kult für die Shen'dar Highlands plant.",
			text = [=[Einem Rekruten, der sich unter die Gläubigen von Falaath mischte, wurde gesagt, er solle sich vom Gasthaus fernhalten, wo der Himmelspriester einen Gast empfing. Der Gast war Lorthuna. Ihre Befehle waren kurz. Sie hatte andere Geschäfte, und dies war nur ein Teil ihres Spiels. {link:skypriest-aanders}Aanders{/link} sollte den westlichen Wachturm nehmen und Cyclas {link:shen-dar-village}Shen'dar Village{/link}.]=],
		},
		{
			title = "Das Leuchtfeuer",
			hint = "Folgt der Hohepriesterin zu den Spitzen über ihrem Schrein.",
			text = [=[Auf den Spitzen sagte Lorthuna ihren Feinden, sie kämen zu spät. Die Schutzbanne seien schon seit Tagen gefallen. Sie entzünde ein Leuchtfeuer. Als der Fürst des Ostwinds kam, grüßte sie ihn und bat darum, als Herold seiner Herrlichkeit vor den Windfürsten gebracht zu werden. {link:rohash}Rohash{/link} schlug sie beiseite und schleuderte sie in den endlosen Himmel.]=],
		},
	},
	mentions = {
		{ text = "Schläger der {link:al-aketh}Al'Aketh{/link}" },
		{ text = "Zehnfach gerächt" },
		{ text = "Die wahren Pläne des Kults" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "ihre einstige Schwester" },
		{ id = "skypriest-aanders", name = "Himmelspriester Aanders", note = "ihr Diener in Falaath" },
		{ id = "belathaan-brightwish", name = "Belathaan Brightwish", note = "der Gesandte, den sie tötete" },
		{ id = "rohash", name = "Rohash", note = "beantwortete ihr Leuchtfeuer" },
		{ id = "al-akir", name = "Al'Akir", note = "der Herr, dem sie diente" },
	},
})

Translate("deDE", "rohash", {
	title = "Rohash",
	subtitle = "Fürst des Ostwinds",
	found = "Die Rohashi Spires, über dem Shrine of Akir",
	hint = [=[Stellt Euch dem Fürsten des Windes, der das Leuchtfeuer des Kults beantwortete.]=],
	allegiance = "Al'Akir · Skywall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rohash ist der Fürst des Ostwinds, einer der großen Fürsten der Luft, die {link:al-akir}Al'Akir{/link} in {link:skywall}Skywall{/link} dienen. Er ist mächtig, spöttisch und erfreut sich am Leiden geringerer Wesen. Er kam nach {link:zephras-isle}Zephras Isle{/link}, als Lorthunas Leuchtfeuer ihn rief.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rohash ist der erste Diener des Windfürsten, von dem man weiß, dass er {link:zephras-isle}Zephras Isle{/link} gesehen hat. Er hatte nie von der Insel oder ihrem Volk gehört. Ihre Entdeckung versetzte ihn in Staunen, und er begriff sofort, was sie bedeutete. Die Geister, die die Elfen beschützt hatten, waren seine eigenen „abtrünnigen Brüder“, und sie hatten die Insel gut verborgen. Da die Schutzbanne fort waren, konnte er das Geheimnis zu seinem Herrn tragen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er beantwortete Lorthunas Leuchtfeuer auf den {link:rohashi-spires}Rohashi Spires{/link}.
• Er warf die Hohepriesterin beiseite, als sie sich anmaßte, ihm zu befehlen.
• Er rief die Heere des Windfürsten gegen die Elfen auf.
• Er zog sich zurück, als der Irdene Ring und die {link:kirin-tor}Kirin Tor{/link} an die Seite der {link:skyborne}shen'dorei{/link} traten.
• Er verspottete die Hoffnung der Elfen, standzuhalten, und sagte, die Heere seines Herrn seien in jenem Reich endlos.]=],
		},
	},
	chapters = {
		{
			title = "Der Fürst des Ostwinds",
			hint = [=[Steht auf den Spitzen, wenn das Leuchtfeuer beantwortet wird.]=],
			text = [=[Rohash lachte über die Elfen und über die Freunde, die sie an niederen Orten gefunden hatten. Er fragte sich laut, ob sein Herr sie versklaven oder bloß verschlingen würde. Als {link:muln-earthfury}Muln Earthfury{/link} ihm sagte, der Ring habe keinen Streit mit ihm, beschloss Rohash zu gehen. Bevor er ging, gab er den Elfen sein Versprechen. Sie seien Gäste im Reich seines Herrn, nur bis das Urteil des Windfürsten komme. Sie würden nicht wissen, wann es komme, aber es werde kommen.]=],
		},
	},
	mentions = {
		{
			text = [=[Stellt {link:high-priestess-lorthuna}Lorthuna{/link} zur Rede]=],
		},
	},
	bonds = {
		{ id = "al-akir", name = "Al'Akir", note = "sein Herr" },
		{ id = "high-priestess-lorthuna", name = "Hohepriesterin Lorthuna", note = "entzündete das Leuchtfeuer, das er beantwortete" },
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "sprach vor ihm für den Irdenen Ring" },
	},
})

Translate("deDE", "altarius", {
	title = "Altarius",
	subtitle = "Der schlafende Drache von Ban'aethal",
	found = "Die Ruins of Ban'aethal",
	hint = [=[Sucht in den Ruinen von Ban'aethal nach dem, was dort schläft.]=],
	allegiance = "Skywall",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Altarius ist ein großer Drache des Windes, ein Geschöpf von {link:skywall}Skywall{/link} selbst. Es heißt, er liege schlafend in den {link:ruins-of-ban-aethal}Ruins of Ban'aethal{/link}, am nordöstlichen Rand von {link:zephras-isle}Zephras Isle{/link}, wo das Land begonnen hat, in den Himmel zu stürzen. Wer ihn weckt, bleibt nicht lange in seiner Gegenwart.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine bisher verzeichnete Erzählung der {link:skyborne}shen'dorei{/link} sagt, warum er nach {link:ruins-of-ban-aethal}Ban'aethal{/link} kam, ob er dem Windfürsten dient oder was er über die verschwundenen Geister weiß. Dieser Eintrag hält nur fest, dass er dort ist.]=],
		},
	},
})

Translate("deDE", "rorian-the-dayseeker", {
	title = "Rorian the Dayseeker",
	subtitle = "Anführer von Thendal Village",
