	},
})

Translate("deDE", "illaya-amberwind", {
	title = "Illaya Amberwind",
	subtitle = "Älteste Windshaper von Shen'dar",
	found = "Die Mitte von Shen'dar Village",
	hint = [=[Sprecht mit der Ältesten der Windshapers in Shen'dar Village.]=],
	allegiance = "Windshapers · Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Illaya Amberwind ist die Älteste der {link:windshapers}Windshapers{/link} in {link:shen-dar-village}Shen'dar Village{/link}. Sie kann die Himmelssicht in denen spüren, die sie tragen, selbst in jenen, die nie als Schamanen ausgebildet wurden. Sie lehrt die Jungen den Zweck ihres Ordens: die verlorenen Geister zu finden und sie heimzubringen.]=],
