	},
	mentions = {
		{ text = "Die {link:windshapers}Windshapers{/link}" },
		{ text = "Aufdringliche Magier" },
	},
	bonds = {
		{ id = "ayessa-dawnsinger", name = "Ayessa Dawnsinger", note = "Große Himmelsseherin ihres Ordens" },
