	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rathiril Sunlance ist der Älteste des {link:high-order}High Order{/link} in {link:shen-dar-village}Shen'dar Village{/link}. Er sieht die Aura des Arkanen in den Jungen hochgeborenen Blutes, und er lehrt sie das Credo seines Ordens. Für ihn war der schwerste Fehler der {link:skyborne}shen'dorei{/link}, ihr Schicksal in die Hände launischer Geister zu legen.]=],
