• Er schickt sie weiter zu {link:elaadrin-evengale}Elaadrin Evengale{/link} in {link:valanaar}Valanaar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Der {link:high-order}High Order{/link}" },
		{ text = "Ein magischer Affront" },
	},
	bonds = {
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "Obermagister seines Ordens" },
		{ id = "illaya-amberwind", name = "Illaya Amberwind", note = "seine Rivalin in Shen'dar" },
	},
})

Translate("deDE", "sania-silverstream", {
	title = "Sania Silverstream",
	subtitle = "Missionarin der Al'Aketh",
	found = "Shen'dar Village",
	hint = [=[Sucht die sanftmütige Missionarin des Kults in Shen'dar Village.]=],
	allegiance = "Al'Aketh",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sania Silverstream predigt für die {link:al-aketh}Al'Aketh{/link} in {link:shen-dar-village}Shen'dar Village{/link}. Sie spielt die Rolle einer sanften Priesterin. Ihr Credo lautet, dass die {link:skyborne}shen'dorei{/link} stolz und träge geworden seien und dass die Geister sie deshalb verlassen hätten. Nur Buße, sagt sie, werde die Berührung des Windes zurückbringen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Sania ist das sanfte Gesicht des Kults. Sie gibt neuen Bekehrten das Zeichen Akirs und schickt sie nach Falaath, und sie warnt, dass der {link:al-akir}Windfürst{/link} jeden bestraft, der unter falschem Vorwand zu seinen Gläubigen kommt.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie predigt in Shen'dar unter den Augen der {link:peacekeepers}Peacekeepers{/link}.
• Sie zeichnet neue Rekruten, damit die Gläubigen sie erkennen.
• Sie schickt sie zu Missionar Jasaan nach Falaath.]=],
		},
	},
	mentions = {
		{ text = "Den Kult unterwandern" },
		{ text = "{link:falaath-village}Falaath Village{/link}" },
	},
	bonds = {
		{ id = "constable-aonda", name = "Konstablerin Aonda", note = "duldete sie, eine Zeit lang" },
		{ id = "high-priestess-lorthuna", name = "Hohepriesterin Lorthuna", note = "ihre Hohepriesterin" },
	},
})

Translate("deDE", "skypriest-aanders", {
