	allegiance = "Familie Windfield",
	aliases = { "Aamelia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aamelia Windfield pflegt den Obstgarten ihrer Familie im Tiefland westlich von {link:valanaar}Valanaar{/link}, wo die Stormapples wachsen. Räuber unter Ferauu the Bludgeon nahmen sich einen Zehnten jeder Ernte, und ihr Mann Alvarion wurde schwer verwundet. Aamelia wollte ihre Bäume nicht aufgeben. Sie entschied sich, standzuhalten und zu kämpfen, was auch immer daraus werden mochte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Aamelia ist eine von vielen gewöhnlichen {link:skyborne}shen'dorei{/link}, die sich selbst überlassen sind, während die Insel zerfällt. Das alte Zyklonkonstrukt ihres Obstgartens, zerbrochen und verwirrt, ist eines der letzten Geschenke der Geister.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie hütete die Ernte, während ihr Mann in {link:valanaar}Valanaar{/link} Hilfe suchte.
• Sie jagte die Räuber, die zwischen ihren Bäumen lauerten.
• Sie ging erhobenen Hauptes hinaus, um Ferauu entgegenzutreten.]=],
		},
	},
	mentions = {
		{ text = "Blutzehnt" },
		{ text = "Macht Euch nützlich" },
		{ text = "Wir halten stand" },
		{ text = "Was ist mein Zweck?" },
	},
	bonds = {
