	},
})

Translate("deDE", "elegael-thornpaw", {
	title = "Elegael Thornpaw",
	subtitle = "Druidin der Nightclaw",
	found = "Der Nordosten des Shadowgale Forest",
	hint = [=[Sucht die verwundete Druidin nahe dem Bau der Nightclaw im Shadowgale Forest.]=],
	allegiance = "Nightclaw-Druiden",
	aliases = { "Elegael" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Elegael Thornpaw ist eine Druidin der Nightclaw, des Zirkels, der abgeschieden im {link:shadowgale-forest}Shadowgale Forest{/link} lebt. Als die {link:al-aketh}Al'Aketh{/link} über ihren Bau herfielen, entkam sie verwundet und floh. Ihr Gefährte, Jorel Windsinger, blieb unter den Verletzten zurück.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Elegael erfuhr, dass der Angriff von Haalien angeführt wurde, einem Druiden ihres eigenen Zirkels, der Monate zuvor verschwunden war. Ein zerrissenes Schreiben bei seinem Leichnam enthüllte, dass jemand in {link:valanaar}Valanaar{/link} den Kult mit Nachrichten versorgte. So wenige {link:skyborne}shen'dorei{/link} sind Druiden, sagt sie, dass jedes Leben kostbar ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bereitete Umschläge aus Lady's-Tear-Moos und Federn der Shrieklings für die Verwundeten.
• Sie schickte Hilfe in den Bau, um die Verletzten zu heilen und ihren Gefährten zu finden.
• Sie schickte das Schreiben des Verräters an Lotheluum in {link:valanaar}Valanaar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Beunruhigende Stille" },
		{ text = "Die Bande, die verbinden" },
		{ text = "Die Wunden des Verrats" },
		{ text = "Das Schicksal des Baus" },
	},
	bonds = {
		{ id = "skypriest-aanders", name = "Himmelspriester Aanders", note = "diente demselben Kult wie ihr Verräter" },
	},
})

Translate("deDE", "urs-endris", {
	title = "Urs'endris",
	subtitle = "Der große windgeborene Bärengeist",
	found = "An den Fällen nordöstlich von Valanaar",
	hint = [=[Sucht den großen Bärengeist nahe den Fällen im Schatten des Shrine of Akir.]=],
	allegiance = "Die Geister von Zephras",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Urs'endris ist ein großer windgeborener Bärengeist von {link:zephras-isle}Zephras Isle{/link}. Seit Generationen lehrt er die Druiden der {link:skyborne}shen'dorei{/link}, die Gestalt der Ursera anzunehmen. Nun verdorrt sein Reich und stürzt in den Himmel, wie so vieles auf der Insel.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Urs'endris zeigt, was das Schweigen der Winde den lebenden Geschöpfen von {link:zephras-isle}Zephras{/link} angetan hat. Ohne die Winde haben viele Tiere sich selbst verloren. Seine eigene Gefährtin, Ur'endra, verfiel dem Wahnsinn und wandte sich gegen ihre Artgenossen, und er bat einen jungen Druiden, ihr Leiden zu beenden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er lehrt die Druiden von {link:zephras-isle}Zephras{/link} die Gestalt der Ursera.
• Er prüft jene, die seinen Segen suchen.
• Er trauert um seine Gefährtin, selbst während er um ihren Tod bittet.]=],
		},
	},
	mentions = {
		{ text = "Der große Ursera-Geist" },
		{ text = "Stärke und Gnade" },
	},
	bonds = {
		{ id = "elegael-thornpaw", name = "Elegael Thornpaw", note = "eine Druidin der Insel" },
	},
})

Translate("deDE", "ealaane-nimbuswalker", {
	title = "Ealaane Nimbuswalker",
	subtitle = "Flüchtling aus Ban'aethal",
	found = "Unter den Flüchtlingen in Valanaar",
	hint = [=[Sprecht mit der Geflüchteten aus Ban'aethal, die in Valanaar wartet.]=],
	allegiance = "Ban'aethal",
	aliases = { "Ealaane" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ealaane Nimbuswalker floh aus {link:ruins-of-ban-aethal}Ban'aethal{/link} in der Nacht, in der das Dorf begann, in den Himmel zu stürzen. Sie wartet mit den anderen Flüchtlingen in {link:valanaar}Valanaar{/link}. Ihr Geliebter, Resaan, ging gegen ihr Flehen zurück, um Vorräte zu holen, und ist nicht wiedergekehrt. Sie fürchtet, dass er tot ist, und sie bittet nur um sein Erbstück.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ealaanes Kummer ist der Kummer der ganzen zerfallenden Insel. Der Boden, der einst ewig schien, kann nun in einer einzigen Nacht unter einem Dorf wegbrechen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bittet Reisende, die in {link:ruins-of-ban-aethal}Ban'aethal{/link} zurückgelassene Habe zu bergen.
• Sie fleht sie an, Resaan zu finden oder wenigstens sein Erbstück heimzubringen.]=],
		},
	},
	mentions = {
		{ text = "Hilfe für die Flüchtlinge" },
		{ text = "Das Schicksal eines geliebten {link:humans}Menschen{/link}" },
	},
	bonds = {
		{ id = "talaanis-shadowsong", name = "Talaanis Shadowsong", note = "Hochältester der Stadt, die ihr Zuflucht gibt" },
	},
})

Translate("deDE", "halaan-hawk-eye", {
	title = "Halaan Hawk-Eye",
	subtitle = "Waldläufer von Thendal Grove",
	found = "Thendal Village",
	hint = [=[Sprecht mit dem Waldläufer, der kommt, um auf den fernen Pylon zu blicken.]=],
	allegiance = "Waldläufer von Thendal Grove",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Halaan Hawk-Eye ist ein Waldläufer von {link:thendal-village}Thendal Grove{/link} mit der Gabe der Fernsicht. Oft kommt er, um auf den uralten {link:anchor-pylons}Ankerpylon{/link} in der Ferne zu blicken. Seine Pracht habe sich nicht verändert, sagt er, doch seine Magie sei unbeständig geworden. Er kann nicht zwischen die Welten sehen und nicht aus den Leylinien schöpfen, aber er ist dankbar für das, was er hat.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Halaan lehrt die Jungen eine kleine Weisheit für ein zerfallendes Zeitalter: zu schätzen, was sie haben, statt zu betrauern, was verloren ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er beobachtet von Thendal aus den {link:anchor-pylons}Ankerpylon{/link}.
• Er leiht den Jungen seine Fernsicht, damit sie den Pylon selbst sehen können.]=],
		},
	},
	mentions = {
		{ text = "Die Anker von {link:zephras-isle}Zephras{/link}" },
	},
	bonds = {
		{ id = "rorian-the-dayseeker", name = "Rorian the Dayseeker", note = "führt sein Dorf" },
	},
})

Translate("deDE", "windshapers", {
	title = "Windshapers",
	aliases = { "Windshaper" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Windshapers sind die Schamanen und Seher der {link:skyborne}Skyborne{/link}. Sie stammen von den ersten shen'dorei ab, die von den Windgeistern die Gabe der Himmelssicht empfingen, die Macht, über die Elementarebene hinwegzusehen. Zeitalter lang waren sie die geistigen Führer von {link:zephras-isle}Zephras Isle{/link}. Sie hüten die heiligen stehenden Steine der Insel, und sie pflegen die Konstrukte und Instrumente, die die Geister zurückließen.]=],
		},
		{
			title = "Ihr Credo",
			text = [=[Die Windshapers halten dafür, dass ihr Volk den Windgeistern eine Schuld schuldet, die niemals ganz beglichen werden kann. Sie haben geschworen, die Geister zu finden und die alten Wege wiederherzustellen. Ohne die Geister, sagen sie, seien sie beinahe blind für das, was in {link:skywall}Skywall{/link} geschieht. Manche von ihnen fürchten, dass die Schuld am Fortgang der Geister bei ihnen selbst liegt. Sie misstrauen dem {link:high-order}High Order{/link}, den sie hochmütige Erben der Hochgeborenen nennen, die meistern wollen, was sie ehren sollten. Wo der High Order in erhobenen Leylinien ein Geschenk sieht, sehen die Windshapers Wunden im Land.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Ihre Magie ist verblasst, seit die Geister fortgingen, und Blut steht zwischen ihnen und dem {link:high-order}High Order{/link}. Ihre Anführerin, die {link:ayessa-dawnsinger}Große Himmelsseherin{/link} Ayessa Dawnsinger, durchsuchte mit ihrer Himmelssicht die Ebenen und fand den {link:earthen-ring}Irdenen Ring{/link} von {link:azeroth}Azeroth{/link}. Durch den Ring haben sich die Windshapers der {link:horde}Horde{/link} angeschlossen. Ihre Vorhut segelt nun von {link:valanaar}Valanaar{/link} nach {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("deDE", "high-order", {
	title = "High Order",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der High Order sind die Magister der {link:skyborne}Skyborne{/link}, die Nachfahren der hochgeborenen Gelehrten von Eldre'Thalas. Sie nennen sich die Hüter der Wege der Hochgeborenen. In zehntausend Jahren in {link:skywall}Skywall{/link} geriet viel von ihrem arkanen Wissen in Vergessenheit, und ihre Macht schwand. Sie wollen es zurückgewinnen.]=],
		},
		{
			title = "Ihr Credo",
			text = [=[Der High Order hält dafür, dass die {link:skyborne}shen'dorei{/link} einen schweren Fehler begingen, als sie ihr Schicksal in die Hände launischer Geister legten. Das Verschwinden der Geister bewies es. Was die Geister einst taten, so glaubt der Orden, lässt sich mit der Magie der {red:highborne}Hochgeborenen{/red} tun, und die Insel kann aus eigener Kraft bestehen. Sie erforschen die erhobenen Leylinien von {link:zephras-isle}Zephras{/link} und die Elementarmagie der stehenden Steine, was auch immer die {link:windshapers}Windshapers{/link} sagen. Für die Windshapers sind sie Störenfriede. Für sich selbst sind sie die Einzigen, die bereit sind zu handeln.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Obermagister {link:elaadrin-evengale}Elaadrin Evengale{/link} fand einen Weg, durch die Ebenen zu spähen, und fand die {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link}, die zurückblickten. Durch die Kirin Tor hat sich der High Order der {link:alliance}Allianz{/link} angeschlossen. Seine jungen Magister segeln nun von {link:valanaar}Valanaar{/link} nach Dalaran, um das Wissen zurückzugewinnen, das ihre Vorfahren verloren.]=],
		},
	},
})

Translate("deDE", "al-aketh", {
	title = "Al'Aketh",
	aliases = { "Kult der Al'Aketh", "Kult des Al'Akir" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Al'Aketh sind ein Kult von {link:skyborne}shen'dorei{/link}, die {link:al-akir}Al'Akir{/link} den Windfürsten anbeten. Einige ihrer Gründer nutzten ihre Himmelssicht, um über {link:skywall}Skywall{/link} zu blicken, und erhaschten einen Blick auf die schreckliche Macht seines Herrn. Von dieser Macht verführt, brachen sie mit ihrem Volk und gaben sich seinem Dienst hin. Als die {link:vanishing-of-the-wind-spirits}Windgeister{/link} verschwanden, erhob sich der Kult in der Furcht, die folgte.]=],
		},
		{
			title = "Ihr Credo",
			text = [=[Der Kult predigt, dass die {link:skyborne}shen'dorei{/link} stolz und träge geworden seien, die Gaben der Winde für selbstverständlich gehalten hätten, und dass die Geister sie deshalb verlassen hätten. Nur Buße und Dienst am Windfürsten würden den Wind zurückbringen. Seine Missionare geben sich als sanfter Glaube. Seine Schläger, Sturmrufer und Meuchler erledigen den Rest. Viele seiner Mitglieder waren einst {link:windshapers}Windshapers{/link}, {link:peacekeepers}Peacekeepers{/link} oder Druiden, und {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link} nennt den Kult ein dunkles Spiegelbild ihres eigenen Ordens.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Unter der {link:high-priestess-lorthuna}Hohepriesterin Lorthuna{/link} hielt der Kult {link:falaath-village}Falaath Village{/link} und den {link:shrine-of-akir}Shrine of Akir{/link}, überfiel die Karawanen der Insel und griff {link:morgan-s-vigil}die Wacht{/link}ürme der Pylonen an, um die Schutzbanne zu Fall zu bringen, die {link:zephras-isle}Zephras{/link} verbargen. Seine Hohepriesterin ist fort und sein Schrein wurde gestürmt, doch sein Ziel wurde erreicht. Die Diener des Windfürsten wissen nun, wo Zephras liegt.]=],
		},
	},
})

Translate("deDE", "peacekeepers", {
	title = "Peacekeepers",
	aliases = { "Peacekeeper" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Peacekeepers sind die Miliz von {link:zephras-isle}Zephras Isle{/link} und das Nächste, was die {link:skyborne}Skyborne{/link} an einem Heer besitzen. Sie unterstehen Hauptfrau {link:valennia-stormfist}Valennia Stormfist{/link} in {link:valanaar}Valanaar{/link} und dem Ältestenrat. Ihre Konstabler wahren die Ordnung in den Dörfern, und ihre Soldaten bemannen {link:morgan-s-vigil}die Wacht{/link}ürme, die die {link:anchor-pylons}Ankerpylonen{/link} bewachen.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Lange mieden die Peacekeepers den offenen Krieg mit den {link:al-aketh}Al'Aketh{/link}, in der Hoffnung, der Kult bliebe ein Ärgernis. Diese Hoffnung endete in {link:shen-dar-village}Shen'dar Village{/link} und an den Wachtürmen der Pylonen. Gering an Zahl, bekämpften sie den Kult über die ganze Insel hinweg und führten den Sturm auf den {link:shrine-of-akir}Shrine of Akir{/link} an. Sie stehen auch zwischen den {link:windshapers}Windshapers{/link} und dem {link:high-order}High Order{/link}, und ihre Hauptfrau duldet nicht, dass die beiden Orden in {link:valanaar}Valanaar{/link} kämpfen. Nicht alle blieben treu. {link:commander-belguilos}Belguilos{/link}, die der Kult nun die Brecherin nennt, trug einst ihre Farben. Unter denen, die standhielten, waren {link:constable-aonda}Konstablerin Aonda{/link} von Shen'dar, die Leutnantin {link:yorana-windyreed}Yorana Windyreed{/link} am östlichen Turm und {link:hyusaa-quickbreeze}Hyusaa Quickbreeze{/link}, die Stellvertreterin der Hauptfrau.]=],
		},
	},
})

Translate("deDE", "anchor-pylons", {
	title = "Ankerpylonen",
	aliases = { "Ankerpylon", "Ankerpylonen", "Windpylonen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ankerpylonen sind uralte Türme der Elementarmagie, Geschenke der {link:vanishing-of-the-wind-spirits}Windgeister{/link} an die {link:skyborne}shen'dorei{/link}. Sie halten {link:zephras-isle}Zephras Isle{/link} zusammen und halten es an seinem Platz in {link:skywall}Skywall{/link}. Wachtürme der {link:peacekeepers}Peacekeepers{/link} stehen neben ihnen, einer im westlichen Hochland und einer vor {link:valanaar}Valanaar{/link}.]=],
		},
		{
			title = "Ihr Versagen",
			text = [=[Seit die Geister verschwanden, sind die Pylonen unbeständig geworden. Ihre Pracht hat sich nicht verändert, und kein Schaden ist zu sehen, doch ihre Magie gerät ins Stocken. Während sie schwächer wird, zerbröckeln Teile der Insel und stürzen in den Himmel. Die {link:skyborne}shen'dorei{/link} schöpfen nun aus Windsteinen, um ihren täglichen Bedarf zu decken, und der {link:high-order}High Order{/link} hofft, die Magie der Pylonen zu meistern, bevor sie endgültig versagt.]=],
		},
		{
			title = "Die Schutzbanne",
			text = [=[Einen zweiten Zweck hatten die {link:skyborne}shen'dorei{/link} halb vergessen. Die Pylonen sind auch Schutzbanne. Sie schirmten die Insel vor dem Blick all dessen ab, was sonst noch in {link:skywall}Skywall{/link} haust. Der {link:flight-from-eldre-thalas}Shal'nan{/link} sprach einst davon, und die {link:al-aketh}Al'Aketh{/link} erfuhren es. Sie griffen die Pylonen an, um die Schutzbanne zu Fall zu bringen, und es gelang ihnen. {link:zephras-isle}Zephras{/link} schwebt noch, doch verborgen ist es nicht mehr.]=],
		},
	},
})

Translate("deDE", "vanishing-of-the-wind-spirits", {
	title = "Das Verschwinden der Windgeister",
	aliases = { "Windgeister" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tausende von Jahren lebten Geister des Windes auf {link:zephras-isle}Zephras Isle{/link} an der Seite der {link:skyborne}shen'dorei{/link}, als Schutzherren, Lehrer und Freunde. Sie hoben die Insel empor, pflegten ihre Magie und schenkten ihren Sehern die Himmelssicht. Dann, vor mehreren Jahrhunderten, verschwanden sie. Sie gaben keine Warnung, und niemand auf Zephras weiß, warum sie gingen oder wohin.]=],
		},
		{
			title = "Was folgte",
			text = [=[Die Magie der Insel begann zu verblassen. Die {link:anchor-pylons}Ankerpylonen{/link} gerieten ins Stocken. Die meisten Konstrukte der Geister hörten auf zu arbeiten. Seltsame bleiche Geister, die man Hollows nennt, erschienen im {link:shadowgale-forest}Shadowgale Forest{/link}. Tiere verwilderten, und die niederen Windgeister wurden gewalttätig, wenn man sie aufstörte. Die Verbindung zu den anderen Inseln ging verloren, und ganze Dörfer stürzten in den Himmel. Jede Gruppe deutete den Verlust auf ihre eigene Weise. Die {link:windshapers}Windshapers{/link} wollen die Geister finden und heimrufen. Der {link:high-order}High Order{/link} sagt, die Elfen dürften nie wieder von ihnen abhängen. Die {link:al-aketh}Al'Aketh{/link} predigen, die Geister hätten ein stolzes Volk verlassen und nur der {link:al-akir}Windfürst{/link} bleibe.]=],
		},
	},
})

Translate("deDE", "flight-from-eldre-thalas", {
	title = "Die Flucht aus Eldre'Thalas",
	aliases = { "Rebellion in Eldre'Thalas", "Shal'nan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die {link:skyborne}Skyborne{/link} begannen als Rebellen. Nach dem {link:war-of-the-ancients}Krieg der Ahnen{/link} waren die {red:highborne}Hochgeborenen{/red} von Eldre'Thalas, der Stadt in {link:feralas}Feralas{/link}, die heute {red:dire-maul}Düsterbruch{/red} heißt, ohne den Brunnen, der ihre Magie genährt hatte. Prinz {red:tortheldrin}Tortheldrin{/red} suchte sie mit immer dunkleren Mächten zu erhalten. Einige seiner Leute hatten gesehen, wohin ein solcher Hunger führte, und sie wollten nicht zulassen, dass Azsharas Fehler noch einmal begangen wurden.]=],
		},
		{
			title = "Der Verhüllte",
			text = [=[Die Rebellen wurden von einer Gestalt angeführt, die man nur als den Shal'nan kannte, den Verhüllten, der sein Gesicht hinter einer gesichtslosen Maske aus Gold verbarg. Sein Name wurde zum Schlachtruf. Durch Sabotage und Schlimmeres behinderten seine Anhänger das Netz kristallener Foki des Prinzen und beschämten ihn wieder und wieder. In jenen Tagen verbreitete sich auch das Druidentum der {link:night-elves}Nachtelfen{/link} des Nordens in der Stadt, und der Prinz verurteilte es als niedrig. Die Rebellen leisteten ihren letzten Widerstand in seinem Heiligtum. Sie wendeten das Schlimmste ab, doch die meisten von ihnen starben.]=],
		},
		{
			title = "Die Flucht",
			text = [=[Die Überlebenden flohen nach Westen, die Flotte des Prinzen hinter sich. Jenseits des Meeres fanden sie ein Land, über das uralte Geister herrschten, und dort schlossen sie ihren Pakt mit dem Wind. Die Geister hoben das Land nach {link:skywall}Skywall{/link} empor, und die Verbannten wurden zu den {link:skyborne}shen'dorei{/link}, dem verborgenen Volk. Mit der Zeit legte der Shal'nan seine Herrschaft nieder und übergab sie einem von seinem Volk gewählten Rat.]=],
		},
	},
})
